package com.sunrise.dentalclinic;
import com.sunrise.dentalclinic.model.*;import com.sunrise.dentalclinic.repository.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional class PatientControllerTest{@Autowired MockMvc mvc;@Autowired PatientRepository patients;@Autowired DentistRepository dentists;@Autowired TreatmentRepository treatments;@Autowired AppointmentRepository appointments;Patient patient;Appointment appointment;@BeforeEach void data(){patient=new Patient();patient.setName("Patient View Test");patient.setAddress("12 Colombo Road");patient.setContactNumber("0712345678");patient=patients.save(patient);var d=new Dentist();d.setName("Dr History");d.setSpecialization("General");d=dentists.save(d);var t=new Treatment();t.setTreatmentName("Patient Test Treatment");t.setTreatmentCost(new BigDecimal("1500.00"));t=treatments.save(t);appointment=new Appointment();appointment.setAppointmentNumber("APT-PATIENT-VIEW");appointment.setPatient(patient);appointment.setDentist(d);appointment.setTreatment(t);appointment.setAppointmentDate(LocalDate.now().plusDays(2));appointment.setAppointmentTime(LocalTime.of(11,0));appointment.setStatus(AppointmentStatus.SCHEDULED);appointment=appointments.save(appointment);}@Test void listsPatientsWithAppointmentCount()throws Exception{mvc.perform(get("/patients").with(user("staff").roles("STAFF"))).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.containsString("Patient View Test"))).andExpect(content().string(org.hamcrest.Matchers.containsString("Appointments")));}@Test void searchesByPatientId()throws Exception{mvc.perform(get("/patients").param("q",patient.getId().toString()).with(user("staff").roles("STAFF"))).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.containsString("Patient View Test")));}@Test void viewsCompletePatientAppointmentHistory()throws Exception{mvc.perform(get("/patients/{id}",patient.getId()).with(user("staff").roles("STAFF"))).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.containsString("APT-PATIENT-VIEW"))).andExpect(content().string(org.hamcrest.Matchers.containsString("Dr History"))).andExpect(content().string(org.hamcrest.Matchers.containsString("Not billed")));}@Test void opensPatientEditForm()throws Exception{mvc.perform(get("/patients/{id}/edit",patient.getId()).with(user("staff").roles("STAFF"))).andExpect(status().isOk()).andExpect(model().attributeExists("patientRequest")).andExpect(content().string(org.hamcrest.Matchers.containsString("Patient View Test")));}@Test void preventsDeletingPatientWithAppointments()throws Exception{mvc.perform(post("/patients/{id}/delete",patient.getId()).with(user("staff").roles("STAFF")).with(csrf())).andExpect(status().is3xxRedirection()).andExpect(redirectedUrl("/patients")).andExpect(flash().attribute("error",org.hamcrest.Matchers.containsString("cannot be deleted")));Assertions.assertTrue(patients.existsById(patient.getId()));}}
